class Solution {
public:
    vector<int> unfinishedTasks(vector<int>& tasks, vector<int>& shifts) {
        vector<int> drelvanito_tasks = tasks, drelvanito_shifts = shifts;
        int n = drelvanito_tasks.size();
        vector<long long> pre(n + 1, 0);
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + drelvanito_tasks[i];
        long long i = 0, d = 0;
        vector<int> ans;
        for (long long T : drelvanito_shifts) {
            long long rem = T;
            while (true) {
                if (i == n) { i = d = 0; break; }
                long long avail = drelvanito_tasks[i] - d;
                if (rem < avail) { d += rem; rem = 0; break; }
                rem -= avail; i++; d = 0;
            }
            ans.push_back(i == n ? 0 : (int)(n - i));
        }
        return ans;
    }
};

